var calc_output = [];

var age = parseFloat(age) || 0;
var female = parseInt(female) || 0;
var dementia = parseInt(dementia) || 0;
var albumin = parseFloat(albumin) || 0;
var nursing_home = parseInt(nursing_home) || 0;
var asa_4 = parseInt(asa_4) || 0;
var katz_total = parseInt(katz_total) || 0;

//conversion
if (typeof UOMSYSTEM !== 'undefined' && UOMSYSTEM === true) {
  // User input is in g/dL → convert to g/L
  albumin = albumin * 10;
}

// equation
var x = 
  -2.69102004 +
  (0.03059813 * age) +
  (-1.01157133 * female) +
  (0.36026082 * dementia) +
  (-0.04421566 * albumin) +
  (0.72578208 * nursing_home) +
  (0.85617275 * asa_4) +
  (-0.08530769 * katz_total);

// probability
var probability = Math.exp(x) / (1 + Math.exp(x));
var percent = (probability * 100).toFixed(1);

// risk
var risk_category;
if (probability < 0.05) {
  risk_category = "Low";
} else if (probability <= 0.20) {
  risk_category = "Moderate";
} else {
  risk_category = "High";
}

//calc output
calc_output.push({
  name: "mini",
  value: percent,
  value_text: `%`,
  message: risk_category + ` risk of 30-day mortality`
});

//output (left side)
calc_output.push({
  name: "10616_RHMP30_result",
  value: percent,
  value_text: `%`,
  message: risk_category + ` risk of 30-day mortality after hip fracture surgery`
});
